mapper.select:
/*CmpyCodeMapper - selectCodeGroupList*/ SELECT cmpy_type_cd AS cmpyTypeCd, cd_group AS cdGroup, cd_group_nm AS cdGroupNm, rmrk_cn AS rmrkCn, use_yn AS useYn, cd_plcus_cd AS cdPlcusCd, TO_CHAR(reg_dt, 'YYYY-MM-DD HH24:MI:SS') AS regDt FROM cdm_own.cmpt_cmpy_cd_group WHERE cmpy_type_cd = #{cmpyTypeCd}
AND (cd_group LIKE '%' || #{cdGroup} || '%') OR (cd_group_nm LIKE '%' || #{cdGroup} || '%')
ORDER BY cd_group ASC

SELECT COUNT(*)
FROM cdm_own.cmpt_cmpy_cd_group
WHERE cmpy_type_cd = #{cmpyTypeCd}
AND cd_group = #{cdGroup}

SELECT COUNT(*)
FROM cdm_own.cmpt_cmpy_cd
WHERE cmpy_type_cd = #{cmpyTypeCd}
AND cd_group = #{cdGroup}
AND cd = #{cd}
AND locale = #{locale}

mapper.update:
UPDATE cdm_own.cmpt_cmpy_cd
SET cd_nm = #{cdNm},
    cd_se = #{cdSe},
    use_yn = COALESCE(#{useYn}, '1'),
    sort_sn = COALESCE(#{sortSn}, 1),
    mdfr_id = 'system',
    mdfcn_dt = NOW()
WHERE cmpy_type_cd = #{cmpyTypeCd}
AND cd_group = #{cdGroup}
AND cd = #{cd}
AND locale = #{locale}
